import { omit as omit0, filter as filter0, traverse } from "@lincode/utils";
export const assign = (setState, getState) => (val) => {
    const state = getState();
    if (state &&
        Object.entries(val).some(([key, value]) => state[key] !== value))
        setState({ ...state, ...val });
};
const isObject = (obj) => obj && typeof obj === "object";
const isMergeable = (obj0, obj1) => {
    if (Array.isArray(obj0) && Array.isArray(obj1))
        return true;
    if (isObject(obj0) && isObject(obj1))
        return true;
    return false;
};
const merge0 = (obj0, obj1) => {
    if (Array.isArray(obj0) && Array.isArray(obj1)) {
        for (let i = 0; i < obj1.length; ++i)
            if (i < obj0.length) {
                if (isMergeable(obj0[i], obj1[i]))
                    merge0(obj0[i], obj1[i]);
                else
                    obj0[i] = obj1[i];
            }
            else
                obj0.push(obj1[i]);
        return obj0;
    }
    for (const [key, value] of Object.entries(obj1)) {
        //@ts-ignore
        if (isMergeable(obj0[key], value))
            merge0(obj0[key], value);
        //@ts-ignore
        else
            obj0[key] = value;
    }
    return obj0;
};
export const merge = (setState, getState) => (val) => {
    const state = getState();
    state && setState({ ...merge0(state, val) });
};
export const omit = (setState, getState) => (val) => {
    const state = getState();
    //@ts-ignore
    state && setState(omit0(state, val));
};
export const filter = (setState, getState) => (predicate) => {
    const state = getState();
    if (!state)
        return;
    if (Array.isArray(state))
        setState(state.filter(predicate));
    else
        setState(filter0(state, predicate));
};
export const rename = (setState, getState) => (from, to) => {
    const state = getState();
    if (!state)
        return;
    if (typeof state === "string") {
        //@ts-ignore
        state === from && setState(to);
        return;
    }
    if (Array.isArray(state)) {
        let update = false;
        const newState = state.map((val) => {
            if (val === from) {
                update = true;
                return to;
            }
            return val;
        });
        //@ts-ignore
        update && setState(newState);
        return;
    }
    //@ts-ignore
    if (!(from in state))
        return;
    //@ts-ignore
    setState(Object.assign(omit0(state, from), { [to]: state[from] }));
};
export const renameStartsWith = (setState, getState) => (from, to) => {
    const state = getState();
    if (!state)
        return;
    if (typeof state === "string") {
        //@ts-ignore
        state.startsWith(from) && setState(state.replace(from, to));
        return;
    }
    if (Array.isArray(state)) {
        let update = false;
        const newState = state.map((val) => {
            if (val.startsWith(from)) {
                update = true;
                return val.replace(from, to);
            }
            return val;
        });
        //@ts-ignore
        update && setState(newState);
        return;
    }
    const replaced = {};
    const filtered = filter0(state, (v, k) => {
        //@ts-ignore
        const replace = k.startsWith(from);
        //@ts-ignore
        replace && (replaced[k.replace(from, to)] = v);
        return !replace;
    });
    if (Object.keys(replaced).length === 0)
        return;
    //@ts-ignore
    setState(Object.assign(filtered, replaced));
};
export const increase = (setState, getState) => () => setState(getState() + 1);
export const decrease = (setState, getState) => () => setState(getState() - 1);
export const add = (setState, getState) => (val) => {
    const [set] = getState();
    if (set.has(val))
        return;
    set.add(val);
    setState([set]);
};
export const remove = (setState, getState) => (val) => {
    const [set] = getState();
    if (!set.has(val))
        return;
    set.delete(val);
    setState([set]);
};
export const clear = (setState, getState) => () => {
    const [set] = getState();
    if (!set.size)
        return;
    set.clear();
    setState([set]);
};
export const push = (setState, getState) => (val) => {
    const array = getState();
    array && setState([...array, val]);
};
export const pull = (setState, getState) => (val) => {
    const array = getState();
    array && setState(array.filter((item) => item !== val));
};
export const concat = (setState, getState) => (val) => {
    const array = getState();
    array && setState([...array, ...val]);
};
export const refresh = (setState, getState) => () => {
    const state = getState();
    if (!state)
        return;
    if (Array.isArray(state))
        //@ts-ignore
        setState([...state]);
    else
        setState({ ...state });
};
export const reset = (setState, getState) => {
    const state = getState();
    if (state && typeof state === "object") {
        traverse(state, (_, v) => Object.freeze(v));
        Object.freeze(state);
    }
    return () => setState(state);
};
